import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_23_her_overview.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_23_goal_interface.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_23_replay_contrast.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_23_relabel_flow.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_23_her_driving_boundary.png",g=JSON.parse('{"title":"失败也能变经验：目标条件强化学习与 HER 讲透了","description":"如果任务奖励只有“是否到达目标”，失败轨迹通常全部得到零分。Hindsight Experience Replay（事后经验回放，HER）不要求重新设计复杂奖励，而是回头看一条失败轨迹实际到达了什么状态，把那个状态临时当作目标重新计算奖励。原本“没有完成原目标”的经验，就变成“完成了另一个目标”的成","frontmatter":{"title":"失败也能变经验：目标条件强化学习与 HER 讲透了","description":"如果任务奖励只有“是否到达目标”，失败轨迹通常全部得到零分。Hindsight Experience Replay（事后经验回放，HER）不要求重新设计复杂奖励，而是回头看一条失败轨迹实际到达了什么状态，把那个状态临时当作目标重新计算奖励。原本“没有完成原目标”的经验，就变成“完成了另一个目标”的成","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":8,"source":"2026-08-13/rl_series_23_her_goal_conditioned_rl.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_23_her_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-23-her-goal-conditioned-rl"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"失败也能变经验：目标条件强化学习与 HER 讲透了"}],["meta",{"property":"og:description","content":"如果任务奖励只有“是否到达目标”，失败轨迹通常全部得到零分。Hindsight Experience Replay（事后经验回放，HER）不要求重新设计复杂奖励，而是回头看一条失败轨迹实际到达了什么状态，把那个状态临时当作目标重新计算奖励。原本“没有完成原目标”的经验，就变成“完成了另一个目标”的成"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-23-her-goal-conditioned-rl"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_23_her_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"失败也能变经验：目标条件强化学习与 HER 讲透了"}],["meta",{"name":"twitter:description","content":"如果任务奖励只有“是否到达目标”，失败轨迹通常全部得到零分。Hindsight Experience Replay（事后经验回放，HER）不要求重新设计复杂奖励，而是回头看一条失败轨迹实际到达了什么状态，把那个状态临时当作目标重新计算奖励。原本“没有完成原目标”的经验，就变成“完成了另一个目标”的成"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_23_her_overview.png"}]],"prev":{"text":"任务太难学不会？课程学习如何把成功区域一步步推远","link":"/rl/rl-series-22-curriculum-learning"},"next":{"text":"一个目标太大怎么办？分层强化学习与 Options 框架","link":"/rl/rl-series-24-hierarchical-options"}},"headers":[],"relativePath":"rl/rl-series-23-her-goal-conditioned-rl.md","filePath":"rl/rl-series-23-her-goal-conditioned-rl.md","lastUpdated":null}'),d={name:"rl/rl-series-23-her-goal-conditioned-rl.md"};function c(p,a,_,u,b,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="失败也能变经验-目标条件强化学习与-her-讲透了" tabindex="-1">失败也能变经验：目标条件强化学习与 HER 讲透了 <a class="header-anchor" href="#失败也能变经验-目标条件强化学习与-her-讲透了" aria-label="Permalink to &quot;失败也能变经验：目标条件强化学习与 HER 讲透了&quot;">​</a></h1><p>如果任务奖励只有“是否到达目标”，失败轨迹通常全部得到零分。Hindsight Experience Replay（事后经验回放，HER）不要求重新设计复杂奖励，而是回头看一条失败轨迹实际到达了什么状态，把那个状态临时当作目标重新计算奖励。原本“没有完成原目标”的经验，就变成“完成了另一个目标”的成功经验。</p><p>HER 的关键不是把失败说成成功，而是把任务定义成 Goal-Conditioned Reinforcement Learning（目标条件强化学习）：策略、状态价值和奖励函数都显式接收目标。这样同一条轨迹可以针对多个目标重新解释。它适合目标可描述、奖励可重算、算法支持异策略回放的任务，不适合任意不可逆或目标语义模糊的问题。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-目标必须进入策略输入" tabindex="-1">1.1 目标必须进入策略输入 <a class="header-anchor" href="#_1-1-目标必须进入策略输入" aria-label="Permalink to &quot;1.1 目标必须进入策略输入&quot;">​</a></h3><p>策略应表示为 (\\pi(a|s,g))，其中 (g) 是目标。没有目标条件接口，就无法重标记同一转移。</p><h3 id="_1-2-her-重算的是目标相关奖励" tabindex="-1">1.2 HER 重算的是目标相关奖励 <a class="header-anchor" href="#_1-2-her-重算的是目标相关奖励" aria-label="Permalink to &quot;1.2 HER 重算的是目标相关奖励&quot;">​</a></h3><p>状态、动作和下一状态保持不变，只替换训练目标 (g) 并调用同一个奖励函数重新计算 (r(s,a,g))。</p><h3 id="_1-3-her-是隐式课程而非魔法成功" tabindex="-1">1.3 HER 是隐式课程而非魔法成功 <a class="header-anchor" href="#_1-3-her-是隐式课程而非魔法成功" aria-label="Permalink to &quot;1.3 HER 是隐式课程而非魔法成功&quot;">​</a></h3><p>它让智能体先学习“我能到达什么”，再逐步接近原任务目标。若替代目标选择不当，策略仍可能学到无关行为。</p><h3 id="_1-4-her-依赖异策略算法和正确终止语义" tabindex="-1">1.4 HER 依赖异策略算法和正确终止语义 <a class="header-anchor" href="#_1-4-her-依赖异策略算法和正确终止语义" aria-label="Permalink to &quot;1.4 HER 依赖异策略算法和正确终止语义&quot;">​</a></h3><p>回放重标记天然要求样本可重复使用，DDPG、TD3、SAC 或其他异策略方法更适配；同策略方法不能直接照搬。</p><p><img src="'+l+'" alt="HER 将失败轨迹重解释为替代目标经验"></p><h2 id="二、什么是目标条件强化学习" tabindex="-1">二、什么是目标条件强化学习 <a class="header-anchor" href="#二、什么是目标条件强化学习" aria-label="Permalink to &quot;二、什么是目标条件强化学习&quot;">​</a></h2><h3 id="_2-1-目标是任务输入的一部分" tabindex="-1">2.1 目标是任务输入的一部分 <a class="header-anchor" href="#_2-1-目标是任务输入的一部分" aria-label="Permalink to &quot;2.1 目标是任务输入的一部分&quot;">​</a></h3><p>普通策略只看状态，目标条件策略同时看当前状态和目标。目标可以是位置、姿态、物体配置或离散任务标签。</p><h3 id="_2-2-奖励函数由目标决定" tabindex="-1">2.2 奖励函数由目标决定 <a class="header-anchor" href="#_2-2-奖励函数由目标决定" aria-label="Permalink to &quot;2.2 奖励函数由目标决定&quot;">​</a></h3><p>常见稀疏奖励为：</p><p>$$ r(s,a,g)=\\begin{cases}0,&amp;\\text{若达到目标 }g\\-1,&amp;\\text{否则}\\end{cases} $$</p><p>不同目标对同一转移可以给出不同奖励。</p><h3 id="_2-3-观测、目标和-achieved-goal-要分开" tabindex="-1">2.3 观测、目标和 achieved goal 要分开 <a class="header-anchor" href="#_2-3-观测、目标和-achieved-goal-要分开" aria-label="Permalink to &quot;2.3 观测、目标和 achieved goal 要分开&quot;">​</a></h3><p>环境通常提供 observation、desired goal 和 achieved goal。三者混在一个向量里会让奖励重算、日志和调试变得不透明。</p><h3 id="_2-4-目标空间决定泛化方式" tabindex="-1">2.4 目标空间决定泛化方式 <a class="header-anchor" href="#_2-4-目标空间决定泛化方式" aria-label="Permalink to &quot;2.4 目标空间决定泛化方式&quot;">​</a></h3><p>连续位置目标要求几何泛化，离散目标要求类别泛化，多阶段任务还要明确目标是否包含顺序和约束。</p><p><img src="'+h+'" alt="目标条件强化学习的 observation、desired goal 与 achieved goal 接口"></p><h2 id="三、普通回放为什么浪费失败轨迹" tabindex="-1">三、普通回放为什么浪费失败轨迹 <a class="header-anchor" href="#三、普通回放为什么浪费失败轨迹" aria-label="Permalink to &quot;三、普通回放为什么浪费失败轨迹&quot;">​</a></h2><h3 id="_3-1-原目标失败导致奖励全相同" tabindex="-1">3.1 原目标失败导致奖励全相同 <a class="header-anchor" href="#_3-1-原目标失败导致奖励全相同" aria-label="Permalink to &quot;3.1 原目标失败导致奖励全相同&quot;">​</a></h3><p>无论车辆偏左、偏右还是停在起点，只要没到原目标，稀疏奖励都可能是同一个负值。</p><h3 id="_3-2-价值网络看不到实际进展" tabindex="-1">3.2 价值网络看不到实际进展 <a class="header-anchor" href="#_3-2-价值网络看不到实际进展" aria-label="Permalink to &quot;3.2 价值网络看不到实际进展&quot;">​</a></h3><p>如果某条轨迹已经到达一个有意义的中间位置，但原目标奖励不区分它，评论家无法学习“到这里是有价值的”。</p><h3 id="_3-3-重新设计距离奖励会引入投机" tabindex="-1">3.3 重新设计距离奖励会引入投机 <a class="header-anchor" href="#_3-3-重新设计距离奖励会引入投机" aria-label="Permalink to &quot;3.3 重新设计距离奖励会引入投机&quot;">​</a></h3><p>距离塑形需要领域知识，可能改变最优行为。HER 试图只重用已有目标语义和奖励函数。</p><h3 id="_3-4-失败轨迹仍包含可学习的控制技能" tabindex="-1">3.4 失败轨迹仍包含可学习的控制技能 <a class="header-anchor" href="#_3-4-失败轨迹仍包含可学习的控制技能" aria-label="Permalink to &quot;3.4 失败轨迹仍包含可学习的控制技能&quot;">​</a></h3><p>轨迹记录了如何移动、如何避障和如何改变物体状态。换目标后，这些动作就可以获得非零训练信号。</p><p><img src="'+o+'" alt="没有 HER 与加入 HER 时回放信息量的差异"></p><h2 id="四、her-怎样重标记一条轨迹" tabindex="-1">四、HER 怎样重标记一条轨迹 <a class="header-anchor" href="#四、her-怎样重标记一条轨迹" aria-label="Permalink to &quot;四、HER 怎样重标记一条轨迹&quot;">​</a></h2><h3 id="_4-1-先按原目标执行轨迹" tabindex="-1">4.1 先按原目标执行轨迹 <a class="header-anchor" href="#_4-1-先按原目标执行轨迹" aria-label="Permalink to &quot;4.1 先按原目标执行轨迹&quot;">​</a></h3><p>行为策略使用当前目标 (g) 交互，保存 ((s_t,a_t,s_{t+1},g)) 和 achieved goal。</p><h3 id="_4-2-从轨迹中采样替代目标" tabindex="-1">4.2 从轨迹中采样替代目标 <a class="header-anchor" href="#_4-2-从轨迹中采样替代目标" aria-label="Permalink to &quot;4.2 从轨迹中采样替代目标&quot;">​</a></h3><p>替代目标可选未来达到的状态、当前回合曾经达到的状态或最终达到的状态。不同策略影响成功信号密度。</p><h3 id="_4-3-只替换目标并重算奖励" tabindex="-1">4.3 只替换目标并重算奖励 <a class="header-anchor" href="#_4-3-只替换目标并重算奖励" aria-label="Permalink to &quot;4.3 只替换目标并重算奖励&quot;">​</a></h3><p>对替代目标 (g&#39;)：</p><p>$$ r&#39;_t=r(s_t,a_t,g&#39;) $$</p><p>状态转移和动作不被伪造，改变的是“这条经验要完成哪个目标”的解释。</p><h3 id="_4-4-将原始和重标记样本混合回放" tabindex="-1">4.4 将原始和重标记样本混合回放 <a class="header-anchor" href="#_4-4-将原始和重标记样本混合回放" aria-label="Permalink to &quot;4.4 将原始和重标记样本混合回放&quot;">​</a></h3><p>保留一部分原目标样本，避免策略完全忘记任务；同时控制 HER 比例，防止替代目标分布压过真实目标。</p><p><img src="'+n+'" alt="HER 的原目标与替代目标重算流程"></p><h2 id="五、替代目标怎样选择" tabindex="-1">五、替代目标怎样选择 <a class="header-anchor" href="#五、替代目标怎样选择" aria-label="Permalink to &quot;五、替代目标怎样选择&quot;">​</a></h2><h3 id="_5-1-最终目标策略稳定但多样性有限" tabindex="-1">5.1 最终目标策略稳定但多样性有限 <a class="header-anchor" href="#_5-1-最终目标策略稳定但多样性有限" aria-label="Permalink to &quot;5.1 最终目标策略稳定但多样性有限&quot;">​</a></h3><p>把回合最终达到的状态作为替代目标通常简单有效，适合成功定义明确的任务。</p><h3 id="_5-2-未来目标策略提供更多密集信号" tabindex="-1">5.2 未来目标策略提供更多密集信号 <a class="header-anchor" href="#_5-2-未来目标策略提供更多密集信号" aria-label="Permalink to &quot;5.2 未来目标策略提供更多密集信号&quot;">​</a></h3><p>从当前时刻之后的 achieved goals 采样，可以让早期动作学习通往后续状态的技能。</p><h3 id="_5-3-随机策略不一定适合长时域任务" tabindex="-1">5.3 随机策略不一定适合长时域任务 <a class="header-anchor" href="#_5-3-随机策略不一定适合长时域任务" aria-label="Permalink to &quot;5.3 随机策略不一定适合长时域任务&quot;">​</a></h3><p>目标太近会让任务过于简单，目标太远又回到稀疏困难。应结合距离、时间和成功率调节。</p><h3 id="_5-4-替代目标必须保持语义合法" tabindex="-1">5.4 替代目标必须保持语义合法 <a class="header-anchor" href="#_5-4-替代目标必须保持语义合法" aria-label="Permalink to &quot;5.4 替代目标必须保持语义合法&quot;">​</a></h3><p>不能把不可能的姿态、违反道路约束的位置或跨任务标签随意拼成目标。否则奖励函数本身失去物理意义。</p><h2 id="六、her-与异策略算法如何配合" tabindex="-1">六、HER 与异策略算法如何配合 <a class="header-anchor" href="#六、her-与异策略算法如何配合" aria-label="Permalink to &quot;六、HER 与异策略算法如何配合&quot;">​</a></h2><h3 id="_6-1-q-learning-类方法可重复利用旧行为" tabindex="-1">6.1 Q-learning 类方法可重复利用旧行为 <a class="header-anchor" href="#_6-1-q-learning-类方法可重复利用旧行为" aria-label="Permalink to &quot;6.1 Q-learning 类方法可重复利用旧行为&quot;">​</a></h3><p>HER 样本的动作来自历史行为策略，异策略算法可以在当前目标条件下学习它们的价值。</p><h3 id="_6-2-ddpg、td3-和-sac-的接口不同" tabindex="-1">6.2 DDPG、TD3 和 SAC 的接口不同 <a class="header-anchor" href="#_6-2-ddpg、td3-和-sac-的接口不同" aria-label="Permalink to &quot;6.2 DDPG、TD3 和 SAC 的接口不同&quot;">​</a></h3><p>连续动作算法要把目标拼接进 Actor 和 Critic 输入，并确保动作缩放、目标归一化和奖励重算一致。</p><h3 id="_6-3-目标网络读取重标记后的目标" tabindex="-1">6.3 目标网络读取重标记后的目标 <a class="header-anchor" href="#_6-3-目标网络读取重标记后的目标" aria-label="Permalink to &quot;6.3 目标网络读取重标记后的目标&quot;">​</a></h3><p>目标评论家、目标演员和主网络必须使用同一个 (g&#39;)，不能只替换主损失的一侧。</p><h3 id="_6-4-回放池需要保存足够的原始信息" tabindex="-1">6.4 回放池需要保存足够的原始信息 <a class="header-anchor" href="#_6-4-回放池需要保存足够的原始信息" aria-label="Permalink to &quot;6.4 回放池需要保存足够的原始信息&quot;">​</a></h3><p>若只保存最终奖励而不保存 achieved goal，就无法在采样时重新计算替代目标奖励。</p><h2 id="七、her-的局限与失败模式" tabindex="-1">七、HER 的局限与失败模式 <a class="header-anchor" href="#七、her-的局限与失败模式" aria-label="Permalink to &quot;七、HER 的局限与失败模式&quot;">​</a></h2><h3 id="_7-1-到达目标不等于完成任务" tabindex="-1">7.1 到达目标不等于完成任务 <a class="header-anchor" href="#_7-1-到达目标不等于完成任务" aria-label="Permalink to &quot;7.1 到达目标不等于完成任务&quot;">​</a></h3><p>车辆到达某个坐标但姿态、速度或交通规则不满足，不能算真正成功。目标定义应包含任务所需约束。</p><h3 id="_7-2-目标可达性假设可能不成立" tabindex="-1">7.2 目标可达性假设可能不成立 <a class="header-anchor" href="#_7-2-目标可达性假设可能不成立" aria-label="Permalink to &quot;7.2 目标可达性假设可能不成立&quot;">​</a></h3><p>有些目标在动力学或障碍条件下不可达，重标记后仍然没有有效学习信号。</p><h3 id="_7-3-分布偏移仍然存在" tabindex="-1">7.3 分布偏移仍然存在 <a class="header-anchor" href="#_7-3-分布偏移仍然存在" aria-label="Permalink to &quot;7.3 分布偏移仍然存在&quot;">​</a></h3><p>替代目标经验可能覆盖训练策略容易到达的区域，而原目标位于分布边缘。HER 不是完全消除探索。</p><h3 id="_7-4-目标归一化错误会破坏泛化" tabindex="-1">7.4 目标归一化错误会破坏泛化 <a class="header-anchor" href="#_7-4-目标归一化错误会破坏泛化" aria-label="Permalink to &quot;7.4 目标归一化错误会破坏泛化&quot;">​</a></h3><p>状态、目标和 achieved goal 的尺度必须一致。坐标范围不一致会让网络把数值尺度误当成任务差异。</p><p><img src="'+s+'" alt="HER 在自动驾驶目标定义中的可行域边界"></p><h2 id="八、一个最小实验怎样设计" tabindex="-1">八、一个最小实验怎样设计 <a class="header-anchor" href="#八、一个最小实验怎样设计" aria-label="Permalink to &quot;八、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_8-1-采用二维稀疏导航环境" tabindex="-1">8.1 采用二维稀疏导航环境 <a class="header-anchor" href="#_8-1-采用二维稀疏导航环境" aria-label="Permalink to &quot;8.1 采用二维稀疏导航环境&quot;">​</a></h3><p>策略输入位置和目标位置，只有到达目标才给非负奖励，障碍和最大步数单独定义。</p><h3 id="_8-2-比较普通回放和-her-回放" tabindex="-1">8.2 比较普通回放和 HER 回放 <a class="header-anchor" href="#_8-2-比较普通回放和-her-回放" aria-label="Permalink to &quot;8.2 比较普通回放和 HER 回放&quot;">​</a></h3><p>保持算法、网络、环境步和目标集合一致，比较首次成功、最终成功率、目标泛化和回放目标分布。</p><h3 id="_8-3-做替代目标策略消融" tabindex="-1">8.3 做替代目标策略消融 <a class="header-anchor" href="#_8-3-做替代目标策略消融" aria-label="Permalink to &quot;8.3 做替代目标策略消融&quot;">​</a></h3><p>分别比较最终目标、未来目标和随机目标策略，记录目标距离、成功率与训练稳定性。</p><h3 id="_8-4-检查原目标评估" tabindex="-1">8.4 检查原目标评估 <a class="header-anchor" href="#_8-4-检查原目标评估" aria-label="Permalink to &quot;8.4 检查原目标评估&quot;">​</a></h3><p>训练时的 HER 奖励不能作为最终成绩。评估必须关闭重标记，使用未见原目标和真实任务约束。</p><h2 id="九、最常见的实现错误" tabindex="-1">九、最常见的实现错误 <a class="header-anchor" href="#九、最常见的实现错误" aria-label="Permalink to &quot;九、最常见的实现错误&quot;">​</a></h2><h3 id="_9-1-只替换奖励不替换目标输入" tabindex="-1">9.1 只替换奖励不替换目标输入 <a class="header-anchor" href="#_9-1-只替换奖励不替换目标输入" aria-label="Permalink to &quot;9.1 只替换奖励不替换目标输入&quot;">​</a></h3><p>网络仍看到旧目标，会导致奖励与状态条件不一致。</p><h3 id="_9-2-使用重标记后的奖励评估算法" tabindex="-1">9.2 使用重标记后的奖励评估算法 <a class="header-anchor" href="#_9-2-使用重标记后的奖励评估算法" aria-label="Permalink to &quot;9.2 使用重标记后的奖励评估算法&quot;">​</a></h3><p>这样会把“完成替代目标”误报成“完成真实目标”。</p><h3 id="_9-3-忘记处理截断和终止" tabindex="-1">9.3 忘记处理截断和终止 <a class="header-anchor" href="#_9-3-忘记处理截断和终止" aria-label="Permalink to &quot;9.3 忘记处理截断和终止&quot;">​</a></h3><p>时间截断、自然终止和目标达到后的终止含义不同，Bellman 目标必须分别处理。</p><h3 id="_9-4-把-her-当作奖励塑形" tabindex="-1">9.4 把 HER 当作奖励塑形 <a class="header-anchor" href="#_9-4-把-her-当作奖励塑形" aria-label="Permalink to &quot;9.4 把 HER 当作奖励塑形&quot;">​</a></h3><p>HER 重解释目标条件经验，不等同于给每一步增加距离奖励。两者的理论和风险不同。</p><h2 id="十、学到什么程度才算掌握" tabindex="-1">十、学到什么程度才算掌握 <a class="header-anchor" href="#十、学到什么程度才算掌握" aria-label="Permalink to &quot;十、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_10-1-能写出目标条件策略接口" tabindex="-1">10.1 能写出目标条件策略接口 <a class="header-anchor" href="#_10-1-能写出目标条件策略接口" aria-label="Permalink to &quot;10.1 能写出目标条件策略接口&quot;">​</a></h3><p>你应能明确 observation、desired goal、achieved goal、reward 和终止信号的输入输出。</p><h3 id="_10-2-能手算一条重标记转移" tabindex="-1">10.2 能手算一条重标记转移 <a class="header-anchor" href="#_10-2-能手算一条重标记转移" aria-label="Permalink to &quot;10.2 能手算一条重标记转移&quot;">​</a></h3><p>你应能在不修改状态和动作的前提下，用新目标重新计算奖励和 Bellman 目标。</p><h3 id="_10-3-能选择替代目标策略" tabindex="-1">10.3 能选择替代目标策略 <a class="header-anchor" href="#_10-3-能选择替代目标策略" aria-label="Permalink to &quot;10.3 能选择替代目标策略&quot;">​</a></h3><p>你应能根据任务时间跨度、目标可达性和回放比例选择最终、未来或混合目标。</p><h3 id="_10-4-能进入分层强化学习" tabindex="-1">10.4 能进入分层强化学习 <a class="header-anchor" href="#_10-4-能进入分层强化学习" aria-label="Permalink to &quot;10.4 能进入分层强化学习&quot;">​</a></h3><p>下一篇将从“目标”继续抽象到“子任务”，解释 Option（选项）如何让策略在多个时间尺度上决策。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://arxiv.org/abs/1707.01495" target="_blank" rel="noreferrer">Andrychowicz 等《Hindsight Experience Replay》</a></p><p><a href="https://openai.com/index/hindsight-experience-replay/" target="_blank" rel="noreferrer">OpenAI HER 论文介绍</a></p><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter10/chapter10.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十章稀疏奖励部分</a></p>',106)])])}const f=e(d,[["render",c]]);export{g as __pageData,f as default};
